// Parse Claude's response and extract qualification data
const input = $input.first().json;
const claudeResponse = input.content?.[0]?.text;

if (!claudeResponse) {
  throw new Error('No response from Claude API');
}

// Extract JSON from Claude's response (handles markdown code blocks)
let qualificationData;
try {
  // Try to find JSON in markdown code blocks
  const jsonMatch = claudeResponse.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) {
    qualificationData = JSON.parse(jsonMatch[1].trim());
  } else {
    // Try to parse the entire response as JSON
    qualificationData = JSON.parse(claudeResponse);
  }
} catch (error) {
  console.error('Failed to parse Claude response:', claudeResponse);
  throw new Error('Invalid JSON response from Claude: ' + error.message);
}

// Validate required fields
const required = ['leadScore', 'extractedBudget', 'timeline', 'preapprovalStatus', 'personalizedResponse', 'emailSubject', 'emailBody'];
for (const field of required) {
  if (!qualificationData[field]) {
    throw new Error(`Missing required field: ${field}`);
  }
}

return [{
  json: {
    ...qualificationData,
    rawResponse: claudeResponse,
    processedAt: new Date().toISOString()
  }
}];

